	}
}
"},{"node":"RebuildMemoPayload","qualified_name":"bench-repo.server.runner.memopayload.RebuildMemoPayload","label":"Function","file":"server/runner/memopayload/runner.go","start_line":74,"end_line":88,"in_degree":3,"out_degree":1,"match_lines":[74],"source":"func RebuildMemoPayload(_ context.Context, memo *store.Memo, markdownService markdown.Service) error {
	if memo.Payload == nil {
		memo.Payload = &storepb.MemoPayload{}
	}

	// Use goldmark service to extract all metadata in a single pass (more efficient)
	data, err := markdownService.ExtractAll([]byte(memo.Content))
	if err != nil {
		return errors.Wrap(err, "failed to extract markdown metadata")
	}

	memo.Payload.Tags = data.Tags
	memo.Payload.Property = data.Property
	return nil
}
